  const found: string[] = [];
  for (const [table, column, value] of rows) {
    const { rowCount } = await pool.query(`select 1 from ${table} where ${column} = $1`, [value]);
    if (rowCount) found.push(`${table}.${column}`);
  }
  return found;
}

